 layout:()=>({key:'drive',moveLabel:'Steer / Pedals',buttons:[{id:'throttle',label:'Gas',hold:true},{id:'brake',label:'Brake',hold:true},{id:'handbrake',label:'Drift',hold:true},{id:'camera',label:'Camera',side:'top'},{id:'recover',label:'Recover',secondary:true},{id:'horn',label:'Horn',secondary:true},{id:'pause',label:'Pause',side:'top'}],help:'Steer with the left stick. Hold a pedal to drive; hold Drift (the handbrake) through a turn to drift.'}),
 move(x,y){if(!mobileMode()||!active||!['playing','countdown'].includes(state))return;mobileInput.x=Math.max(-1,Math.min(1,x));mobileInput.y=Math.max(-1,Math.min(1,y));audio.unlock();},
 action(id,down){if(!down&&['throttle','brake','handbrake'].includes(id)){mobileInput[id]=false;return;}if(!mobileMode()||!active||!['playing','countdown'].includes(state))return;audio.unlock();if(['throttle','brake','handbrake'].includes(id)){mobileInput[id]=down;return;}if(!down)return;if(id==='pause')pause();else if(id==='camera')cycleCamera();else if(id==='recover'&&state==='playing')sim.recovery();else if(id==='horn')audio.horn();},
