function menu(){wreckMenu=false;clearCreditStreak();setState('menu');if(scene)scene.setCar(configFor(),colorFor(save.selected));panels.innerHTML=`<section class="drive-panel drive-title-panel"><div class="drive-kicker">Four roads. Thirteen machines.</div><h1>platdo<span>Drive</span></h1><p class="drive-tagline">Find your line.</p><nav class="drive-menu-buttons"><button class="primary" data-action="modes">Drive</button><button data-action="garage">Garage</button><button data-action="records">Records</button><button data-action="settings">Settings</button><button data-action="graphics">Graphics</button><button data-action="controls">Controls</button>${window.PlatdoDriveStandalone?'':'<button class="quiet" data-action="hub">Game selector</button>'}</nav></section>`;updateBalance();}
const mapPreviews=new Map();
function mapPreview(id){if(mapPreviews.has(id))return mapPreviews.get(id);const r=new Core.Route(id),all=[r.samples,...(r.connectors||[]).map(c=>c.samples)],points=all.flat(),xs=points.map(p=>p.x),zs=points.map(p=>p.z),minX=Math.min(...xs),minZ=Math.min(...zs),w=Math.max(...xs)-minX,h=Math.max(...zs)-minZ,scale=Math.min(228/w,98/h),dx=(260-w*scale)/2,dz=(126-h*scale)/2;const path=ss=>ss.filter((_,i)=>i%3===0).map((p,i)=>(i?'L':'M')+(dx+(p.x-minX)*scale).toFixed(1)+','+(dz+(p.z-minZ)*scale).toFixed(1)).join(' ');const result=`<svg viewBox="0 0 260 126" aria-label="${escapeText(r.map.name)} route layout" role="img"><path d="${path(r.samples)} Z" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linejoin="round"/>${all.slice(1).map(c=>`<path d="${path(c)}" fill="none" stroke="currentColor" stroke-opacity=".5" stroke-dasharray="3 3" stroke-width="2"/>`).join('')}<circle cx="${dx+(r.at(18).x-minX)*scale}" cy="${dz+(r.at(18).z-minZ)*scale}" r="4" fill="#fff"/></svg>`;mapPreviews.set(id,result);return result;}
function modeMenu(){setState('modes');const maps=window.DriveMaps.list,current=window.DriveMaps.get(save.selectedMap);panels.innerHTML=`<section class="drive-panel drive-route-panel"><button class="quiet drive-back" data-action="menu">← Main menu</button><div class="drive-kicker">Choose your road</div><h2>${escapeText(current.name)}</h2><div class="drive-map-cards">${maps.map(m=>`<button data-action="map" data-map="${m.id}" aria-pressed="${m.id===save.selectedMap}" class="drive-map-card ${m.id===save.selectedMap?'active':''}">${mapPreview(m.id)}<strong>${escapeText(m.name)}</strong><small>${formatDistance(m.length)} · ${m.connectors.length} connecting road${m.connectors.length===1?'':'s'}</small></button>`).join('')}</div><p class="drive-map-description">${escapeText(current.description)}</p><div class="drive-modes">${Object.entries(modes).map(([id,[name,desc]],i)=>`<article class="drive-mode ${id===save.lastMode?'last-driven':''}"><div class="number">0${i+1}${id===save.lastMode&&save.firstPlayDone?'<small class="drive-last-mode">Last played</small>':''}</div><h3>${name}</h3><p>${typeof desc==='function'?desc():desc}</p>${id==='free'?'<label style="font-size:12px;margin-bottom:15px">Traffic &nbsp; <select id="driveDensity"><option value="low">Light</option><option value="medium">Regular</option><option value="high">Busy</option></select></label>':''}<button class="primary" data-action="begin" data-mode="${id}">Drive ${name} ↗</button></article>`).join('')}</div><p class="drive-rules-note">${settings().damageMode==='cosmetic'?'Cosmetic':'Standard'} damage · Challenge records keep each map, car setup and damage rule separate.</p></section>`;$('#driveDensity').value=density;}
function recordLabel(key){const [,map,,setup,damage]=key.split(':'),[base,parts]=String(setup||'').split('~'),match=/^([a-z]+)-e([0-3])-t([0-3])-b([0-3])$/.exec(base),car=match&&Core.CARS[match[1]],equipment=parts?parts.split('.').map((id,index)=>Core.PARTS[Core.PART_CATEGORIES[index]]?.find(p=>p.id===id)?.name).filter(Boolean).join(' / '):match?'Engine '+match[2]+' / Tires '+match[3]+' / Brakes '+match[4]:'';return [window.DriveMaps.get(map).name,car?car.name:setup,equipment,damage==='cosmetic'?'Cosmetic damage':'Standard damage'].filter(Boolean).join(' · ');}
function records(){setState('records');const entries=Object.entries(save.records||{}).flatMap(([kind,items])=>Object.entries(items).map(([key,v])=>({kind,key,value:typeof v==='number'?v:v[kind==='trial'?'time':'score']})));panels.innerHTML=`<section class="drive-panel drive-record-panel"><button class="quiet drive-back" data-action="menu">← Main menu</button><div class="drive-kicker">Your garage history</div><h2>Records</h2><p>Current records are separated by road, car upgrades, damage rule and driving rules.</p>${entries.length?`<div class="drive-record-list">${entries.map(e=>`<article><span>${escapeText(e.kind==='trial'?'Time Trial':'Traffic Rush')}</span><strong>${e.kind==='trial'?formatTime(e.value):Math.round(e.value).toLocaleString()+' pts'}</strong><small>${escapeText(recordLabel(e.key))}</small></article>`).join('')}</div>`:'<p>Finish a Time Trial or Traffic Rush to set your first record.</p>'}${Object.keys(save.bestTimes).length||save.bestRush?`<details class="drive-panel-card"><summary>Previous driving rules · preserved records</summary><p>These original records remain saved separately from the upgraded game.</p>${stat('Original Traffic Rush best',save.bestRush.toLocaleString())}${Object.entries(save.bestTimes).map(([k,v])=>stat(k,formatTime(v))).join('')}</details>`:''}</section>`;}

function begin(nextMode){if(!createScene())return;wreckMenu=false;audio._stopVoices('fire');mode=nextMode;save.lastMode=mode;configKey=configFor().key;sim=new Core.Simulation(route,configFor(),{mode,density:mode==='free'?density:'medium',damageMode:settings().damageMode});applyAdmin();clearCreditStreak();lastReward=null;scene.setCar(configFor(),colorFor(save.selected));$('.drive-notice').textContent='';noticeUntil=0;if(settings().tips&&!save.firstPlayDone){setState('tips');panels.innerHTML=`<section class="drive-panel drive-tip-panel"><div class="drive-panel-card"><div class="drive-kicker">A good first mile</div><h2>Find your line.</h2>${mobileMode()?'<p>Steer with the left stick. Hold Gas to drive; hold Brake to slow down, then reverse. Hold Drift as you turn to drift.</p><p>Tap Camera to change your view. Recover returns your car to the road. Pause opens the menu.</p>':`<p><kbd>${keyName(save.bindings.throttle)}</kbd> accelerate · <kbd>${keyName(save.bindings.brake)}</kbd> brake, then reverse.<br><kbd>${keyName(save.bindings.left)}</kbd> <kbd>${keyName(save.bindings.right)}</kbd> steer · <kbd>${keyName(save.bindings.handbrake)}</kbd> handbrake.</p><p>Ease off before a bend. Tap the steering to settle into your line. Follow the lane markings and watch for oncoming traffic.</p><p><kbd>${keyName(save.bindings.camera)}</kbd> camera · <kbd>${keyName(save.bindings.recover)}</kbd> recover · <kbd>Esc</kbd> pause.</p>`}<button class="primary" data-action="ready">Let’s drive ↗</button></div></section>`;}else ready();}
function ready(){save.firstPlayDone=true;writeSave();countdown=mode==='free'?0:3;setState(countdown?'countdown':'playing');renderHUD();}
function pause(){if(!['playing','countdown'].includes(state))return;pausedState=state;setState('paused');panels.innerHTML=`<section class="drive-panel drive-pause-panel"><div class="drive-panel-card"><div class="drive-kicker">${modes[mode][0]}</div><h2>Take a breath.</h2><div class="drive-menu-buttons"><button class="primary" data-action="resume">Resume</button><button data-action="garage">Garage</button><button data-action="restart">Restart</button>${mode==='free'?'<button data-action="repair">Repair &amp; recover · Free</button>':''}<button data-action="settings">Settings</button><button data-action="graphics">Graphics</button><button data-action="admin">Admin controls</button><button data-action="menu">Main menu</button></div></div></section>`;}
function resume(){setState(pausedState);}
function results(){if(sim?.player.destroyed){showWreckMenu();return;}if(state==='results'||!sim?.result)return;clearCreditStreak();const result=sim.result;lastReward=Core.settleResult(save,result,configKey);writeSave();setState('results');const trial=mode==='trial';panels.innerHTML=`<section class="drive-panel drive-results-panel"><div class="drive-panel-card"><div class="drive-kicker">${trial?(result.medal||'Finish')+' · Time Trial':'Traffic Rush · Run complete'}</div><h2>${trial?formatTime(result.time):Math.round(result.score).toLocaleString()+' pts'}</h2><div class="drive-stat-grid">${trial?stat('Best · this setup',formatTime(recordValue('trial')))+stat('Recovery penalties','+'+(result.penalty||0).toFixed(0)+'s'):stat('Personal best',Math.round(recordValue('rush')||0).toLocaleString())+stat('Clean overtakes',result.overtakes)+stat('Near misses',result.nearMisses)+stat('Condition',Math.round(result.condition)+'%')}${stat('Distance',formatDistance(result.distance))}${stat('Credits earned','+'+(lastReward?.credits||0)+' CR')}</div><div class="drive-row"><button class="primary" data-action="restart">Drive again ↗</button><button data-action="garage">Garage</button><button class="quiet" data-action="menu">Main menu</button></div></div></section>`;updateBalance();audio.confirm();}
// Admin tuning is session-only; a touched challenge stays assisted even if reset.
function applyAdmin(){
 if(!sim)return;const base=configFor(),target=admin.speed===null?base.maxSpeed:admin.speed/2.2369362921;
 sim.config={...base,maxSpeed:target,accel:base.accel*admin.acceleration*Math.max(1,(target/base.maxSpeed)**2),grip:base.grip*admin.traction,brake:base.brake*admin.brakes};sim.admin={invincible:admin.invincible,invincibleRailGuards:admin.invincibleRailGuards,steering:admin.steering};
 if(admin.invincible||admin.speed!==null||['acceleration','traction','steering','brakes'].some(k=>admin[k]!==1))sim.assisted=true;
}
function showWreckMenu(first=true){
 if(!sim?.player.destroyed)return;
 if(first){bankDrivingCredits();lastReward=Core.settleResult(save,sim.result,configKey);writeSave();clearCreditStreak();}
 wreckMenu=true;setState('wrecked');root.classList.add('drive-wreck');
 panels.innerHTML=`<section class="drive-panel drive-wreck-panel"><div class="drive-panel-card"><div class="drive-kicker">0% condition</div><h2>WRECKED</h2><p>The road keeps moving.</p><div class="drive-stat-grid">${stat('Distance',formatDistance(sim.result?.distance||sim.distance))}${stat('Banked',save.credits.toLocaleString()+' CR')}</div><div class="drive-menu-buttons"><button class="primary" data-action="restart">New car · Drive again</button><button data-action="settings">Settings</button><button data-action="graphics">Graphics</button><button data-action="admin">Admin controls</button><button data-action="menu">Main menu</button>${window.PlatdoDriveStandalone?'':'<button class="quiet" data-action="hub">Game selector</button>'}</div></div></section>`;updateBalance();
}
function openAdmin(){adminBack=state==='paused'?'paused':wreckMenu?'wrecked':state==='settings'?'settings':'menu';if(state==='playing'||state==='countdown'){pause();adminBack='paused';}setState('admin');adminPanel();}
function adminPanel(){
 if(state!=='admin'){adminBack=settingsBack==='paused'?'paused':settingsBack==='wrecked'?'wrecked':'settings';setState('admin');}
 const range=(key,label,min,max,step,value,suffix='×')=>field(label,`<input aria-label="${label}" type="range" data-admin="${key}" min="${min}" max="${max}" step="${step}" value="${value}"><output class="drive-value">${Number(value).toFixed(step<1?2:0)}${suffix}</output>`);
 const content=admin.unlocked?field('Invincibility',`<input aria-label="Invincibility" type="checkbox" data-admin="invincible" ${admin.invincible?'checked':''}>`,'Stops new damage. Other cars can still break.')+field('invincible rail guards',`<input aria-label="invincible rail guards" type="checkbox" data-admin="invincibleRailGuards" ${admin.invincibleRailGuards?'checked':''}>`,'Intact guardrails remain solid at any speed. Broken openings stay open until a new drive.')+range('speed','Speed limiter (mph)',10,400,5,admin.speed??Math.round(configFor().maxSpeed*2.2369362921),' mph')+range('acceleration','Acceleration',.25,8,.25,admin.acceleration)+range('traction','Tire traction',.1,4,.1,admin.traction)+range('steering','Steering response',.25,3,.25,admin.steering)+range('brakes','Braking force',.25,4,.25,admin.brakes)+field('Give yourself credits',`<input id="driveAdminMoney" aria-label="Credits to add" type="number" min="1" max="1000000000" step="1" value="10000"><button data-action="adminMoney">Add CR</button>`)+`<p class="drive-admin-status" role="status" id="driveAdminStatus"></p><button data-action="adminReset">Restore standard physics</button><p class="drive-rules-note">Tuning lasts for this session and applies immediately. Modified challenge runs are unranked. Granted credits save with your garage.</p>`:`<p>Enter the admin code to open vehicle tuning.</p><div class="drive-row"><input id="driveAdminCode" aria-label="Admin code" inputmode="numeric" type="password" maxlength="6" autocomplete="off"><button class="primary" data-action="adminUnlock">Unlock</button></div><p id="driveAdminStatus" class="drive-admin-status" role="status"></p>`;
 panels.innerHTML=`<section class="drive-panel drive-settings drive-admin-panel"><button class="quiet drive-back" data-action="adminBack">← Back</button><div class="drive-kicker">Garage tools</div><h2>Admin controls</h2><div class="drive-panel-card">${content}</div></section>`;
}
function unlockAdmin(){if($('#driveAdminCode')?.value!=='177161'){$('#driveAdminStatus').textContent='Incorrect code.';return;}admin.unlocked=true;adminPanel();}
function leaveAdmin(){if(adminBack==='paused'){state=pausedState;pause();}else if(adminBack==='wrecked')showWreckMenu(false);else if(adminBack==='settings'){state='menu';openSettings('main');}else menu();}
function updateAdminControl(input){if(!admin.unlocked)return;const key=input.dataset.admin;if(!Object.hasOwn(admin,key)||key==='unlocked')return;admin[key]=['invincible','invincibleRailGuards'].includes(key)?input.checked:Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)));if(input.nextElementSibling?.tagName==='OUTPUT')input.nextElementSibling.textContent=Number(admin[key]).toFixed(Number(input.step)<1?2:0)+(key==='speed'?' mph':'×');applyAdmin();}
function grantAdminMoney(){if(!admin.unlocked||!saving)return;const amount=Number($('#driveAdminMoney')?.value);if(!Number.isSafeInteger(amount)||amount<1||amount>1e9){$('#driveAdminStatus').textContent='Enter a whole number from 1 to 1,000,000,000.';return;}const added=Math.min(amount,1e9-save.credits);save.credits+=added;writeSave();updateBalance();$('#driveAdminStatus').textContent='Added '+added.toLocaleString()+' CR · '+save.credits.toLocaleString()+' CR available.';}
function stat(label,value){return `<div><small>${escapeText(label)}</small><strong>${escapeText(value)}</strong></div>`;}
function updateBalance(){$('#driveBalance').textContent=save.credits.toLocaleString()+' CR';}
function bankDrivingCredits(){if(!saving||mode!=='free'||!sim)return;const reward=Core.settleFreeDriveCredits(save,sim);if(reward.awarded){writeSave();updateBalance();addCreditStreak(reward.credits);}}
function createGaragePreview(){
 if(garageScene)return true;
 try{garageCanvas=document.createElement('canvas');garageCanvas.className='drive-garage-canvas';garageCanvas.setAttribute('aria-label','Car preview. Drag to rotate in Inspect mode or draw in Paint mode.');garageCanvas.tabIndex=0;garageScene=new window.DriveScene(garageCanvas,route);garageScene.inspection={yaw:.75,distance:5,elevation:2.6,embedded:true};garageScene.setSettings({...settings(),quality:graphicsControl.get().detail,graphicsValues:graphicsControl.get()});garageSim=new Core.Simulation(route,configFor(garageCar),{mode:'free',density:'low',damageMode:'cosmetic'});garageSim.traffic=[];bindGarageCanvas();return true;}catch(e){garageScene?.dispose();garageScene=null;garageCanvas=null;garageSim=null;console.error('Garage preview unavailable',e);toast('The garage preview could not open. Try a lower Graphics setting.');return false;}
}
function disposeGarage(){finishGarageGesture();garageScene?.dispose();garageScene=null;garageSim=null;garageCanvas=null;}
function resizeGarage(){if(!garageScene||!garageCanvas?.isConnected)return;const r=garageCanvas.getBoundingClientRect();if(r.width<1||r.height<1)return;const size=graphicsControl?graphicsControl.renderSize(r.width,r.height):P.renderSize(r.width,r.height);garageScene.resize(size.width,size.height);}
function garage(id=save.selected){
 if(!Core.CARS[id]||!createScene())return;
 const entering=state!=='garage';finishGarageGesture();if(entering){if(['playing','countdown'].includes(state))pause();garageBack=state==='paused'?'paused':'menu';garageEntrySelection=save.selected;garageTool='inspect';garageTab='parts';garageOption=null;}
 if(garageCar!==id)garageOption=null;garageCar=id;if(!createGaragePreview())return;setState('garage');garageSim.config=configFor(id);garageScene.setCar(garageSim.config,garageSim.config.paintColor||colorFor(id));
 const car=Core.CARS[id],owned=save.owned.includes(id),cars=Object.values(Core.CARS),index=cars.findIndex(c=>c.id===id),scroll=$('.drive-garage-panel')?.scrollTop||0;
 panels.innerHTML=`<section class="drive-panel drive-garage-panel"><div class="drive-garage-header"><button class="quiet drive-back" data-action="garageBack">← ${garageBack==='paused'?'Return to pause':'Main menu'}</button><span class="drive-garage-saved">${garageBack==='paused'?'Session paused · changes save automatically':'Changes save automatically'}</span><b class="drive-credits">${save.credits.toLocaleString()} CR</b></div><div class="drive-car-nav"><button data-action="carStep" data-direction="-1" aria-label="Previous car">‹</button><label class="drive-car-select"><span>CAR ${String(index+1).padStart(2,'0')} / ${cars.length}</span><select id="driveGarageCar" aria-label="Select car to inspect">${cars.map((c,i)=>`<option value="${c.id}" ${c.id===id?'selected':''}>${String(i+1).padStart(2,'0')} · ${escapeText(c.name)}${save.owned.includes(c.id)?'':' · '+c.price.toLocaleString()+' CR'}</option>`).join('')}</select></label><button data-action="carStep" data-direction="1" aria-label="Next car">›</button></div><div class="drive-garage-layout"><div class="drive-garage-view"><div class="drive-preview-stage"><div class="drive-preview-label"><span>${owned?(save.selected===id?'CURRENT CAR':'OWNED'):'AVAILABLE TO PURCHASE'}</span><h2>${escapeText(car.name)}</h2></div><div id="driveGarageCanvasSlot"></div><div class="drive-inspection"><button data-action="rotateCar" data-direction="-1" aria-label="Rotate car left">↶</button><button data-action="rotateCar" data-direction="1" aria-label="Rotate car right">↷</button><button data-action="elevateCar" data-direction="1" aria-label="Raise inspection view">↑</button><button data-action="elevateCar" data-direction="-1" aria-label="Lower inspection view">↓</button><button data-action="zoomCar" data-direction="-1" aria-label="Zoom in">＋</button><button data-action="zoomCar" data-direction="1" aria-label="Zoom out">−</button></div><div class="drive-preview-hint">${garageTool==='paint'&&owned?'PAINT · draw directly on the body':'INSPECT · drag the car to rotate'}</div></div><div class="drive-stat-caption">Equipped performance <span>${car.mass.toLocaleString()} kg · ${escapeText(car.drivetrain||'')}</span></div>${garageStats(id)}<p class="drive-garage-description">${escapeText(car.description)}</p><button class="primary drive-select-car" data-action="purchase" ${owned&&save.selected===id?'disabled':''}>${owned?(save.selected===id?'Selected for driving':'Select for driving'):car.price.toLocaleString()+' CR · Purchase car'}</button></div><aside class="drive-garage-customize"><nav class="drive-workshop-tabs"><button data-action="garageTab" data-tab="parts" class="${garageTab==='parts'?'active':''}" aria-pressed="${garageTab==='parts'}">Performance parts</button><button data-action="garageTab" data-tab="paint" class="${garageTab==='paint'?'active':''}" aria-pressed="${garageTab==='paint'}">Paint studio</button></nav><div id="driveGarageTools">${garageTab==='paint'?garagePaintHTML(owned):garagePartsHTML(owned)}</div><p class="drive-garage-footnote">${owned?'Equipment and paint are kept separately for every car.':'Purchase this car to equip parts or paint its body.'} Earn credits by driving or completing challenges.</p></aside></div></section>`;
 $('#driveGarageCanvasSlot').append(garageCanvas);garageCanvas.dataset.painting=String(garageTool==='paint'&&owned);$('.drive-garage-panel').scrollTop=scroll;resizeGarage();updateBalance();
}
function garageStats(id){const c=configFor(id),s=Core.getPerformanceStats(c),unit=settings().units==='mph'?'mph':'km/h',factor=settings().units==='mph'?2.236936:3.6;return `<div class="drive-garage-stats" aria-label="Effective equipped vehicle statistics">${stat('Top speed',(s.topSpeed*factor).toFixed(0)+' '+unit)}${stat('Acceleration',s.acceleration.toFixed(1)+' m/s²')}${stat('Traction',s.traction.toFixed(1)+' m/s²')}${stat('Steering response',s.steering.toFixed(2)+' s⁻¹')}${stat('Braking',s.braking.toFixed(1)+' m/s²')}</div>`;}
function garagePartsHTML(owned){
 const config=configFor(garageCar),category=garageCategory,list=Core.PARTS[category],selected=config.equipped[category],part=list.find(p=>p.id===garageOption)||list.find(p=>p.id===selected)||list[0];garageOption=part.id;const purchased=save.customization[garageCar]?.ownedParts[category]?.includes(part.id),equipped=selected===part.id;
 return `<div class="drive-part-categories" aria-label="Part categories">${Core.PART_CATEGORIES.map(key=>`<button data-action="partCategory" data-category="${key}" class="${key===category?'active':''}" aria-pressed="${key===category}">${categoryLabels[key]}</button>`).join('')}</div><div class="drive-equipped-line"><span>EQUIPPED</span><strong>${escapeText(config.parts[category]?.name||'Factory / retained upgrades')}</strong></div><label class="drive-option-label" for="drivePartOption">Choose from 10 ${categoryLabels[category].toLowerCase()}</label><select id="drivePartOption" aria-label="${categoryLabels[category]} option">${list.map((p,i)=>`<option value="${p.id}" ${p.id===part.id?'selected':''}>${String(i+1).padStart(2,'0')} · ${escapeText(p.name)}${selected===p.id?' · EQUIPPED':save.customization[garageCar]?.ownedParts[category]?.includes(p.id)?' · OWNED':' · '+p.price.toLocaleString()+' CR'}</option>`).join('')}</select><div class="drive-part-detail"><h3>${escapeText(part.name)}</h3><p>${escapeText(part.description)}</p><p class="drive-part-effects">${partEffects(part)}</p><button class="primary" data-action="equipPart" ${!owned||equipped?'disabled':''}>${equipped?'Equipped':purchased?'Equip part':part.price.toLocaleString()+' CR · Buy & equip'}</button><button class="quiet drive-factory" data-action="factoryPart" ${!owned||!selected?'disabled':''}>${category==='spoilers'?'Remove spoiler':'Restore factory / retained upgrades'}</button></div><p class="drive-part-note">Choose an option, then buy or equip it to apply its effect. The car and statistics show your equipped parts.</p>`;
}
function partEffects(part){const labels={maxSpeed:'speed',speed:'speed',accel:'acceleration',acceleration:'acceleration',grip:'traction',traction:'traction',steering:'steering',brake:'braking',braking:'braking'};return Object.entries(part.modifiers||{}).filter(([key,value])=>labels[key]&&typeof value==='number').map(([key,value])=>'+'+((value>=1?value-1:value)*100).toFixed(1).replace(/\.0$/,'')+'% '+labels[key]).join(' · ');}
function garagePaintHTML(owned){const paint=configFor(garageCar).paint;return `<div class="drive-paint-mode"><button data-action="paintTool" data-tool="inspect" class="${garageTool==='inspect'?'active':''}" aria-pressed="${garageTool==='inspect'}">Inspect / rotate</button><button data-action="paintTool" data-tool="paint" class="${garageTool==='paint'?'active':''}" aria-pressed="${garageTool==='paint'}" ${owned?'':'disabled'}>Paint on body</button></div><p class="drive-paint-help">Switch to Paint, then draw on the visible body. Use Inspect or the arrow buttons to reach the other sides and roof.</p><label class="drive-paint-field">Brush color <input id="driveBrushColor" type="color" aria-label="Brush color" value="${brushColor}" ${owned?'':'disabled'}></label><label class="drive-paint-field">Brush size <input id="driveBrushSize" type="range" aria-label="Brush size" min=".005" max=".08" step=".005" value="${brushSize}" ${owned?'':'disabled'}><output>${Math.round(brushSize*1000)}</output></label><div class="drive-row drive-paint-actions"><button data-action="undoPaint" ${!owned||!paint.strokes.length?'disabled':''}>Undo stroke</button><button data-action="clearPaint" ${!owned||!paint.strokes.length?'disabled':''}>Clear markings</button></div><div class="drive-body-color"><span>Whole-body base color</span><div class="drive-paints">${Core.PAINTS.map(p=>`<button class="${paint.baseColor===p.color?'active':''}" style="background:${p.color}" aria-label="${p.name} paint" title="${p.name}" data-action="paint" data-paint="${p.id}" ${owned?'':'disabled'}></button>`).join('')}<input id="driveBaseColor" type="color" aria-label="Custom body color" value="${paint.baseColor}" ${owned?'':'disabled'}></div></div><p class="drive-part-note">Glass, lights, tires and trim stay separate. Markings travel with this car into every driving view.</p>`;}
function refreshGarageTools(){if(state!=='garage')return;garageCanvas.dataset.painting=String(garageTool==='paint'&&save.owned.includes(garageCar));$('#driveGarageTools').innerHTML=garageTab==='paint'?garagePaintHTML(save.owned.includes(garageCar)):garagePartsHTML(save.owned.includes(garageCar));}
function returnFromGarage(){
 finishGarageGesture();writeSave();if(garageBack==='paused'&&sim){if(!sim.applyGarageConfig(configFor())){save.selected=garageEntrySelection;writeSave();toast('There is no clear space for this vehicle. Your previous car stays selected.');return;}applyAdmin();scene.setCar(configFor(),configFor().paintColor||colorFor(save.selected));configKey=sim.config.key;state=pausedState;disposeGarage();pause();}else{disposeGarage();menu();}
}
function finishGarageGesture(){if(!garageGesture&&!garagePaintDraft.length)return;const pointer=garageGesture?.pointer;garageGesture=null;if(garagePaintDraft.length&&saving){const result=Core.addPaintStroke(save,garagePaintDraft,garageCar);if(result?.ok===false)toast(result.reason||'Painting could not be saved.');garagePaintDraft=[];garageScene?.setPaint(configFor(garageCar).paint);writeSave();refreshGarageTools();}else garagePaintDraft=[];if(pointer!==undefined&&garageCanvas?.hasPointerCapture(pointer))garageCanvas.releasePointerCapture(pointer);}
function paintGaragePoint(x,y){const hit=garageScene.pickPaint(x,y);if(!hit)return;const previous=garagePaintDraft.at(-1);if(previous&&previous.surface===hit.surface&&Math.hypot(previous.u-hit.u,previous.v-hit.v)<brushSize*.3)return;const base=configFor(garageCar).paint;if(base.strokes.length+garagePaintDraft.length>=1400){if(!garageGesture.full){toast('Paint is full. Undo a stroke or clear markings to make room.');garageGesture.full=true;}return;}garagePaintDraft.push({...hit,r:brushSize,color:brushColor,stroke:garageGesture.stroke});garageScene.setPaint({...base,strokes:[...base.strokes,...garagePaintDraft]});}
function bindGarageCanvas(){
 garageCanvas.addEventListener('contextmenu',e=>e.preventDefault());
 garageCanvas.addEventListener('pointerdown',e=>{if(state!=='garage'||garageGesture||e.button!==0)return;e.preventDefault();clearInput();const painting=garageTool==='paint'&&save.owned.includes(garageCar);garageGesture={pointer:e.pointerId,x:e.clientX,y:e.clientY,painting,stroke:Math.max(0,...configFor(garageCar).paint.strokes.map(s=>s.stroke||0))+1};garageCanvas.setPointerCapture(e.pointerId);if(painting)paintGaragePoint(e.clientX,e.clientY);});
 garageCanvas.addEventListener('pointermove',e=>{if(!garageGesture||garageGesture.pointer!==e.pointerId)return;e.preventDefault();const g=garageGesture,dx=e.clientX-g.x,dy=e.clientY-g.y;if(g.painting){const steps=Math.min(60,Math.max(1,Math.ceil(Math.hypot(dx,dy)/3)));for(let i=1;i<=steps;i++)paintGaragePoint(g.x+dx*i/steps,g.y+dy*i/steps);}else{garageScene.inspection.yaw+=dx*.012;garageScene.inspection.elevation=Math.max(.8,Math.min(6,garageScene.inspection.elevation+dy*.012));}g.x=e.clientX;g.y=e.clientY;});
 for(const event of ['pointerup','pointercancel','lostpointercapture'])garageCanvas.addEventListener(event,e=>{if(garageGesture?.pointer===e.pointerId)finishGarageGesture();});
 garageCanvas.addEventListener('wheel',e=>{if(state!=='garage')return;e.preventDefault();garageScene.inspection.distance=Math.max(3.7,Math.min(9,garageScene.inspection.distance+e.deltaY*.004));},{passive:false});
}
function upgradePrice(kind,id){return Core.UPGRADE_PRICES[kind][save.upgrades[id]?.[kind]||0];}
function field(label,content,hint=''){return `<div class="drive-field"><label>${label}${hint?'<small>'+hint+'</small>':''}</label><div class="drive-row">${content}</div></div>`;}
function selectSetting(key,values){return `<select aria-label="${key}" data-setting="${key}">${values.map(([v,n])=>`<option value="${v}" ${String(settings()[key])===String(v)?'selected':''}>${n}</option>`).join('')}</select>`;}
function sliderSetting(key,min,max,step=1){return `<input aria-label="${key}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${settings()[key]}"><output class="drive-value">${Number(settings()[key]).toFixed(step<1?2:0)}</output>`;}
function checkSetting(key){return `<input aria-label="${key}" type="checkbox" data-setting="${key}" ${settings()[key]?'checked':''}>`;}
function openSettings(tab='main',from=state){if(tab==='graphics'){openGraphics();return;}if(state!=='settings'){settingsBack=from==='paused'?'paused':from==='wrecked'?'wrecked':'menu';setState('settings');}settingsTab=tab;let content='';
if(tab==='main')content=field('License plate',`<input id="driveLicensePlate" aria-label="License plate" type="text" maxlength="8" value="${escapeText(settings().licensePlate)}" autocomplete="off" spellcheck="false"><button data-action="plate">Apply</button>`,'Up to 8 letters, numbers, spaces or dashes. Saved for all your cars.')+field('Speed & distance units',selectSetting('units',[['mph','mph'],['kmh','km/h']]))+field('Damage',selectSetting('damageMode',[['standard','Standard'],['cosmetic','Cosmetic']]),'Standard damage affects steering, power and brakes. Cosmetic keeps visible dents without changing handling. Applied on the next drive.')+field('First-play tips',checkSetting('tips'),'Show a quick introduction before driving.')+'<button class="drive-danger" data-action="reset">Reset platdo Drive progress</button>';
if(tab==='display')content=field('Graphics settings','<button data-action="graphics">Open Graphics</button>','Resolution, distance, lighting, shadows and performance.')+field('Field of view',sliderSetting('fov',55,90))+field('Chase distance',sliderSetting('chaseDistance',4,10,.1),'Metres behind the car.')+field('Chase height',sliderSetting('chaseHeight',1.5,5,.1))+field('Camera shake',sliderSetting('cameraShake',0,1,.05))+field('Speed field of view',checkSetting('speedFov'))+field('Reduced camera motion',checkSetting('reducedMotion'))+field('Show FPS',checkSetting('showFPS'))+field('Frame-rate cap',`<select aria-label="Shared frame-rate cap" id="driveFrameCap">${[30,60,120,240].map(v=>`<option ${P.frameRate===v?'selected':''}>${v}</option>`).join('')}</select>`,'Shared across PLATDO. Physics always run at 120 Hz.');
if(tab==='audio')content=field('Master volume',sliderSetting('master',0,1,.05))+field('Engine',sliderSetting('engine',0,1,.05))+field('Tires',sliderSetting('tires',0,1,.05))+field('Impacts',sliderSetting('impacts',0,1,.05))+field('Traffic & environment',sliderSetting('environment',0,1,.05))+field('Menu music',sliderSetting('music',0,1,.05))+field('Mute all driving-game audio',checkSetting('mute'));
if(tab==='controls')content=controlsHTML();
if(tab==='admin'){adminPanel();return;}
if(tab==='save')content=field('Autosave interval',selectSetting('autosave',Array.from({length:10},(_,i)=>[i+1,(i+1)+' minute'+(i?'s':'')])))+`<p style="margin-top:20px">Last successful save: <b id="driveLastSave">${lastSave||'Not saved this session'}</b></p><div class="drive-row"><button class="primary" data-action="save">Save now</button><button data-action="export">Export save</button><button data-action="import">Import save</button></div><p style="font-size:12px;margin-top:18px">Export a JSON backup to move your cars, credits, records, and controls to another computer. Import replaces only platdo Drive progress.</p>`;
panels.innerHTML=`<section class="drive-panel drive-settings"><button class="quiet drive-back" data-action="settingsBack">← ${settingsBack==='paused'?'Pause menu':settingsBack==='wrecked'?'Wreck menu':'Main menu'}</button><h2>Settings</h2><nav class="drive-tabs">${['main','graphics','display','audio','controls','save','admin'].map(t=>`<button class="${tab===t?'active':''}" data-action="tab" data-tab="${t}">${t}</button>`).join('')}</nav><div class="drive-panel-card">${content}</div></section>`;}
function controlsHTML(){if(mobileMode())return '<p>Mobile controls are active. Change PC / Mobile in the game selector’s Main Settings.</p><div class="drive-field"><label>Steering</label><span>Move the left stick left or right.</span></div><div class="drive-field"><label>Pedals</label><span>Hold Gas or Brake. Keep braking after stopping to reverse. The stick also controls forward and reverse.</span></div><div class="drive-field"><label>Drifting</label><span>Hold Drift (the handbrake) while steering.</span></div><div class="drive-field"><label>Other actions</label><span>Camera, Recover, Horn, and Pause are on-screen buttons.</span></div>';return Object.entries(bindingNames).map(([id,label])=>field(label,`<button class="drive-binding" data-action="bind" data-bind="${id}">${escapeText(keyName(save.bindings[id]))}</button>`,id==='pause'?'Escape always pauses.':id==='throttle'?'Arrow keys also drive when not assigned to another action.':'')).join('')+'<p style="font-size:12px;margin-top:15px">Select a key to remap it. Assigning a key already in use swaps the two actions. Press Escape to cancel.</p><button data-action="defaults">Restore default controls</button>';}
function controls(){setState('controls');panels.innerHTML=`<section class="drive-panel drive-settings"><button class="quiet drive-back" data-action="menu">← Main menu</button><h2>Make yourself at home.</h2><div class="drive-panel-card">${controlsHTML()}</div></section>`;}
function askConfirm(title,text,callback){clearInput();const modal=$('.drive-confirm');modal.hidden=false;modal.innerHTML=`<div class="drive-panel-card"><h2>${title}</h2><p>${text}</p><div class="drive-row"><button id="driveConfirmCancel">Cancel</button><button id="driveConfirmOK" class="primary">Confirm</button></div></div>`;$('#driveConfirmCancel').onclick=()=>{modal.hidden=true;};$('#driveConfirmOK').onclick=()=>{modal.hidden=true;callback();};$('#driveConfirmCancel').focus();}
function resetProgress(){askConfirm('Reset this garage?','This permanently clears platdo Drive cars, credits, records, upgrades, and controls. Other PLATDO games and shared display settings stay unchanged.',()=>{try{for(const key of[SAVE,'pre-upgrade-save-backup','unreadable-save-backup'])storage.remove(key);wreckMenu=false;Object.assign(admin,{unlocked:false,invincible:false,invincibleRailGuards:false,speed:null,acceleration:1,traction:1,steering:1,brakes:1});clearCreditStreak();save=Core.createDefaultSave();density=save.settings.trafficDensity||'medium';lastSave='';scene?.dispose();scene=null;createScene();writeSave();openSettings('main');toast('platdo Drive progress reset.');updateBalance();}catch(_){toast('Reset failed because browser storage is unavailable.');}});}
function exportSave(){const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PlatdoDrive-Save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported. Keep this JSON file with your game.');}
function applyImport(data){let candidate;try{candidate=Core.validateSave(data,true);}catch(e){toast('Import rejected: '+e.message);return false;}askConfirm('Import this save?','Replace this game’s progress with '+candidate.credits.toLocaleString()+' credits and '+candidate.owned.length+' owned car(s)? Other games will not change.',()=>{try{storage.set(SAVE,JSON.stringify(candidate));wreckMenu=false;save=candidate;density=save.settings.trafficDensity||'medium';scene?.dispose();scene=null;createScene();lastSave=new Date().toLocaleTimeString();openSettings('save');updateBalance();toast('Save imported.');}catch(_){toast('Import was not applied: browser storage is unavailable.');}});return true;}
$('#driveImport').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>1048576){toast('Import rejected: save files must be smaller than 1 MB.');return;}try{applyImport(JSON.parse(await file.text()));}catch(_){toast('Import rejected: this is not a valid JSON save.');}};
