function drawMap(){if(!route||!sim)return;const c=$('.drive-map'),ctx=c.getContext('2d'),samples=route.samples;let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity;for(const p of samples){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minZ=Math.min(minZ,p.z);maxZ=Math.max(maxZ,p.z);}const scale=Math.min(305/(maxX-minX),260/(maxZ-minZ)),cx=(minX+maxX)/2,cz=(minZ+maxZ)/2;const xy=p=>[175+(p.x-cx)*scale,155+(p.z-cz)*scale];ctx.clearRect(0,0,350,310);ctx.lineJoin='round';ctx.lineWidth=7;ctx.strokeStyle='#16313fc0';ctx.beginPath();samples.forEach((p,i)=>{const[x,y]=xy(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.closePath();ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#e5ece2';ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#9bbcaf';for(const c of route.connectors||[]){ctx.beginPath();c.samples.forEach((p,i)=>{const[x,y]=xy(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}if(mode==='trial'){(sim.checkpoints||[]).forEach((s,i)=>{const[x,y]=xy(route.at(typeof s==='number'?s:s.s));ctx.beginPath();ctx.arc(x,y,i===sim.checkpointIndex?7:3,0,Math.PI*2);ctx.fillStyle=i<sim.checkpointIndex?'#748476':i===sim.checkpointIndex?'#dcf18b':'#9db1b2';ctx.fill();});}const[x,y]=xy(sim.player);ctx.save();ctx.translate(x,y);ctx.rotate(-sim.player.yaw+Math.PI);ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(6,6);ctx.lineTo(0,3);ctx.lineTo(-6,6);ctx.closePath();ctx.fillStyle='#dcf18b';ctx.fill();ctx.restore();}
function renderHUD(){if(!sim)return;const p=sim.player,speed=Math.abs(p.speed)*(settings().units==='mph'?2.236936:3.6);$('.drive-speed strong').textContent=Math.round(speed);$('.drive-unit').textContent=settings().units==='mph'?'MPH':'KM/H';$('.drive-gear').textContent=p.speed<-.4?'R':Math.abs(p.speed)<.4?'N':p.gear||1;$('.drive-rpm i').style.width=Math.min(100,Math.max(0,(p.engineRPM||0)/(sim.config.redlineRPM||7000)*100))+'%';$('.drive-camera-label').textContent=mobileMode()?camera+' CAMERA':camera+' · '+keyName(save.bindings.camera)+' CAMERA · '+keyName(save.bindings.recover)+' RECOVER';$('.drive-hud-mode').textContent=modes[mode][0];$('.drive-condition').hidden=false;$('.drive-condition i').style.width=Math.max(0,p.condition)+'%';$('.drive-condition i').style.background=p.condition<30?'#f3a185':'#d9ed83';const left=$('.drive-hud-value'),secondary=$('.drive-hud-secondary'),right=$('#driveRightValue'),label=$('#driveRightLabel');
if(mode==='rush'){left.textContent=Math.ceil(Math.max(0,sim.remaining))+'s';secondary.textContent='CONDITION '+Math.round(p.condition)+'%';right.textContent=Math.round(sim.score).toLocaleString();label.textContent=sim.multiplier.toFixed(2)+'× MULTIPLIER';}
else if(mode==='trial'){left.textContent=formatTime(sim.time+(sim.penalty||0));secondary.textContent=(sim.penalty?'+'+sim.penalty+'s PENALTY · ':'')+'CHECKPOINT '+Math.min((sim.checkpointIndex||0)+1,sim.checkpoints.length)+' / '+sim.checkpoints.length+' · '+formatShortDistance(((sim.checkpoints[sim.checkpointIndex]||route.length)-p.s+route.length)%route.length);right.textContent=formatTime(recordValue('trial'));label.textContent='BEST · THIS ROAD & SETUP';}
else{left.textContent=formatDistance(sim.distance);secondary.textContent='CONDITION '+Math.round(p.condition)+'% · +'+(sim.freeDriveCredits||0).toLocaleString()+' CR EARNED';right.textContent=save.credits.toLocaleString()+' CR';label.textContent=Math.round(sim.score).toLocaleString()+' PTS · '+formatShortDistance(100-(sim.eligibleDistance||0)%100,true).toUpperCase()+' TO +10 CR';}
if(p.oncoming)secondary.textContent+=' · ONCOMING';
$('.drive-zone').textContent=route.zone?route.zone(p.s):((p.s/route.length)<.34?'Coastal stretch':p.s/route.length<.68?'Woodland bends':'Tunnel & outskirts');drawMap();}
function processEvents(){for(const e of sim.events.splice(0)){if(e.type==='railBreak'){audio.impact(Math.min(1,e.impact/30),{...e,surface:'metal'});}else if(e.type==='explosion'){audio.explosion(Math.hypot((e.x||0)-sim.player.x,(e.z||0)-sim.player.z));}else if(e.type==='collision'){bankDrivingCredits();breakCreditStreak();audio.impact(Math.min(1,(e.impact||e.damage||10)/35),e);}else if(e.type==='pass'||e.type==='nearMiss'||e.type==='oncoming')notice(e.text||(e.type==='nearMiss'?'NEAR MISS':'CLEAN PASS')+' +'+Math.round(e.points||e.amount||100));else if(e.type==='recovery')notice(mode==='trial'?'Recovered · +5 seconds':mode==='rush'?'Recovered · −200 points · −5 seconds':'Back on the road');else if(e.type==='checkpoint'){notice('CHECKPOINT '+(sim.checkpointIndex||1));audio.confirm();}}}
function stopLoop(){if(rafId!==null){cancelAnimationFrame(rafId);rafId=null;}accumulator=0;}
function startLoop(){if(!active||document.hidden||rafId!==null)return;lastFrame=performance.now();lastRender=0;accumulator=0;rafId=requestAnimationFrame(frame);}
function frame(now){rafId=null;if(!active||document.hidden){lastFrame=now;accumulator=0;return;}rafId=requestAnimationFrame(frame);if(!scene){const uiDt=Math.min(.1,Math.max(0,(now-lastFrame)/1000||0));lastFrame=now;audio.update({}, {},state,uiDt,audioEnvironment());if(now>toastUntil)$('.drive-toast').hidden=true;return;}const realDt=Math.min(.25,Math.max(0,(now-lastFrame)/1000||0));lastFrame=now;const input=getInput();if(state==='countdown'){countdown-=realDt;$('.drive-countdown').textContent=Math.max(1,Math.ceil(countdown));if(countdown<=0){setState('playing');notice('GO · FIND YOUR LINE');audio.confirm();}}else if(state==='playing'){accumulator=Math.min(.25,accumulator+realDt);while(accumulator>=fixed&&state==='playing'){sim.step(fixed,input);stats.steps++;accumulator-=fixed;processEvents();if(sim.finished)results();}bankDrivingCredits();updateCreditStreak();}else if(wreckMenu&&state!=='graphics'&&!audio.focusSuspended&&!document.hidden&&document.hasFocus()){accumulator=Math.min(.25,accumulator+realDt);while(accumulator>=fixed){sim.stepAfterWreck(fixed);stats.steps++;accumulator-=fixed;processEvents();}}
audio.update(sim.player,wreckMenu?{}:input,wreckMenu?'wrecked':state,realDt,audioEnvironment());if(now-toastUntil>0)$('.drive-toast').hidden=true;if(now>noticeUntil)$('.drive-notice').textContent='';
const cap=Math.max(1,P.frameRate||60);if(now-lastRender+0.25<1000/cap)return;const frameMs=Math.max(0,now-lastRender),renderDt=Math.min(.1,frameMs/1000||0);lastRender=now;if(state==='playing')renderCreditStreak();const renderStarted=performance.now();const view=wreckMenu||state==='admin'&&adminBack==='paused'?'playing':['menu','modes','settings','controls','records','admin','graphics'].includes(state)?'menu':state==='garage'?'garage':'playing';if(state==='garage'&&garageScene){garageScene.render(garageSim,'chase',renderDt,'garage');}else{sim.interpolate?.(state==='playing'||wreckMenu?accumulator/fixed:1);scene.render(sim,wreckMenu?'chase':camera,['paused','results'].includes(state)||state==='admin'&&adminBack==='paused'||wreckMenu&&(audio.focusSuspended||document.hidden||!document.hasFocus())?0:renderDt,view);}graphicsControl.sample(frameMs,performance.now()-renderStarted,now);stats.frames++;fpsCounter++;if(now-fpsTime>=1000){measuredFPS=fpsCounter*1000/(now-fpsTime);fpsCounter=0;fpsTime=now;$('.drive-fps').textContent=Math.round(measuredFPS)+' FPS';}if(now-lastHUD>70&&['playing','countdown'].includes(state)){renderHUD();lastHUD=now;}}
function setVisible(visible){wreckMenu=false;active=!!visible;root.hidden=!active;clearInput();lastFrame=performance.now();lastRender=0;if(active){startLoop();resize();menu();document.title='platdo Drive | PLATDO';if(saveWarning){toast(saveWarning);saveWarning='';}}else{stopLoop();clearCreditStreak();setState('hidden');writeSave();}}
window.PlatdoDrive={graphics:graphicsControl,openGraphics,setVisible,begin,pause,resume,menu,modeMenu,selectMap,records,garage,openSettings,applyImport,exportSave,get state(){return state;},get sim(){return sim;},get save(){return save;},get route(){return route;},get scene(){return scene;},get garageScene(){return garageScene;},get garageSim(){return garageSim;},get garageCar(){return garageCar;},get audio(){return audio;},get stats(){return{...stats,fps:measuredFPS};},get admin(){return{...admin};},get camera(){return camera;},get input(){return getInput();},saveNow:writeSave};
